using FleetGraph.Vehicles.Domain;

namespace FleetGraph.Vehicles.Infrastructure.Persistence;

/// <summary>
/// Demo data. Ids are generated by the database in insertion order (1..n); the Service
/// subgraph seed refers to vehicles 1-6 by id.
/// </summary>
internal static class VehiclesSeed
{
    public static IEnumerable<Vehicle> Create(DateTimeOffset now)
    {
        yield return Vehicle.Register("YV1LZ5947W2000001", "ABC123", "Volvo", "FH16", 2022, 182_400, "fleet.north@example.com", now);
        yield return Vehicle.Register("YV1LZ5947W2000002", "DEF456", "Volvo", "FM", 2021, 241_050, "fleet.north@example.com", now);
        yield return Vehicle.Register("YS2R4X20005000003", "GHI789", "Scania", "R 450", 2023, 64_300, "fleet.west@example.com", now);
        yield return Vehicle.Register("WDB9634031L000004", "JKL012", "Mercedes-Benz", "Actros", 2020, 398_700, "fleet.west@example.com", now);
        yield return Vehicle.Register("YV1LZ5947W2000005", "MNO345", "Volvo", "FH Electric", 2024, 21_900, "fleet.south@example.com", now);
        yield return Vehicle.Register("XLRAE47MS0L000006", "PQR678", "DAF", "XF", 2019, 512_300, null, now);
        yield return Vehicle.Register("YV1LZ5947W2000007", "STU901", "Volvo", "FL", 2018, 301_800, "fleet.south@example.com", now);
        yield return Vehicle.Register("YS2R4X20005000008", "VWX234", "Scania", "S 500", 2022, 156_000, null, now);
    }
}
